  VB('overmaken', 'to transfer (money)', 'maak over|maakt over|maken over', 'maakte over|maakten over', 'overgemaakt', 'hebben', 'Ik heb de huur overgemaakt.', 'I transferred the rent.', { theme: 'money', stage: 3 });
