  VB('afhangen van', 'to depend on', 'hang af van|hangt af van|hangen af van', 'hing af van|hingen af van', 'afgehangen van', 'hebben', 'Dat hangt af van je inkomen.', 'That depends on your income.', { theme: 'basics', stage: 3, id: 'afhangen-van' });
  VB('recht hebben op', 'to be entitled to', 'heb recht op|heeft recht op|hebben recht op', 'had recht op|hadden recht op', 'recht gehad op', 'hebben', 'Je hebt recht op zorgtoeslag.', 'You are entitled to healthcare allowance.', { theme: 'money', stage: 3, id: 'recht-hebben-op' });
