  N('gegevens', 'de', 'gegevens', 'data / details', 'Controleer uw gegevens.', 'Check your details.', { theme: 'bureaucracy', stage: 3, note: 'Plural only.' });
  N('wijziging', 'de', 'wijzigingen', 'change / amendment', 'Geef wijzigingen binnen vier weken door.', 'Report changes within four weeks.', { theme: 'bureaucracy', stage: 3 });
