  VB('verzoeken', 'to request (formal)', 'verzoek|verzoekt|verzoeken', 'verzocht|verzochten', 'verzocht', 'hebben', 'Wij verzoeken u het bedrag over te maken.', 'We request you to transfer the amount.', { theme: 'formal', stage: 3 });
