  N('voorstel', 'het', 'voorstellen', 'proposal', 'Ik heb een voorstel.', 'I have a proposal.', { theme: 'meetings', stage: 3 });
  N('actiepunt', 'het', 'actiepunten', 'action point', 'Laten we de actiepunten doornemen.', 'Let us go through the action points.', { theme: 'meetings', stage: 3 });
  N('begroting', 'de', 'begrotingen', 'budget', 'De begroting is te krap.', 'The budget is too tight.', { theme: 'meetings', stage: 3 });
  N('kwartaal', 'het', 'kwartalen', 'quarter', 'Volgend kwartaal starten we.', 'We start next quarter.', { theme: 'meetings', stage: 3 });
  N('doelstelling', 'de', 'doelstellingen', 'objective', 'Onze doelstelling is duidelijk.', 'Our objective is clear.', { theme: 'meetings', stage: 3 });
  VB('voorstellen', 'to propose / suggest', 'stel voor|stelt voor|stellen voor', 'stelde voor|stelden voor', 'voorgesteld', 'hebben', 'Ik stel voor dat we dit uitstellen.', 'I propose that we postpone this.', { theme: 'meetings', stage: 3 });
  VB('bespreken', 'to discuss', 'bespreek|bespreekt|bespreken', 'besprak|bespraken', 'besproken', 'hebben', 'Dat bespreken we volgende week.', 'We will discuss that next week.', { theme: 'meetings', stage: 3 });
  VB('samenvatten', 'to summarise', 'vat samen|vat samen|vatten samen', 'vatte samen|vatten samen', 'samengevat', 'hebben', 'Zal ik het even samenvatten?', 'Shall I summarise it?', { theme: 'meetings', stage: 3 });
  VB('afronden', 'to wrap up', 'rond af|rondt af|ronden af', 'rondde af|rondden af', 'afgerond', 'hebben', 'Laten we afronden.', 'Let us wrap up.', { theme: 'meetings', stage: 3 });
  VB('aansluiten', 'to join', 'sluit aan|sluit aan|sluiten aan', 'sloot aan|sloten aan', 'aangesloten', 'zijn', 'Tom sluit later aan.', 'Tom will join later.', { theme: 'meetings', stage: 3 });
  VB('terugkomen op', 'to come back to', 'kom terug op|komt terug op|komen terug op', 'kwam terug op|kwamen terug op', 'teruggekomen op', 'zijn', 'Daar kom ik zo op terug.', 'I will come back to that in a moment.', { theme: 'meetings', stage: 3, id: 'terugkomen-op' });
  PH('Mag ik daar even op reageren?', 'May I respond to that?', 'Mag ik daar even op reageren? Ik zie het anders.', 'May I respond to that? I see it differently.', { theme: 'meetings', stage: 3, id: 'ph-mag-ik-reageren' });
