  const u7 = [];
  u7.push(lesson('s3u7l1', 'In the meeting: word order for emphasis', 'You can take part in a Dutch meeting: propose, respond, summarise, and use word order (fronting, time-manner-place) to say exactly what you mean.', [
    h('Meeting language'),
    table(['function', 'Dutch'], [['open', '*Zullen we beginnen? Het eerste agendapunt is …'], ['propose', '*Ik stel voor dat we … / Wat mij betreft …'], ['respond', '*Mag ik daar even op reageren? / Daar ben ik het (niet) mee eens.'], ['ask for detail', '*Kun je dat concreter maken? / Is dat haalbaar?'], ['park it', '*Daar kom ik zo op terug. / Dat bespreken we volgende keer.'], ['summarise', '*Even samenvatten: … / Zijn we het daarover eens?'], ['close', '*Laten we afronden. Wie doet wat?']]),
    h('Fronting: put first what matters'),
    p('Anything can stand in first position; the verb stays second and the subject follows it. Use it to link to what was just said or to contrast: `**Dat voorstel** vind ik goed, **het andere** niet.` `**Volgend kwartaal** is dat haalbaar, **dit kwartaal** niet.` `**Daar** kom ik zo op terug.`'),
    h('The middle field: time, manner, place'),
    p('`We bespreken dat **morgen** **uitgebreid** **in de vergadering**.` Pronouns go early: `Ik stuur **het je** morgen.` Definite objects before time, indefinite after: `Ik heb **de notulen** gisteren verstuurd` / `Ik heb gisteren **een voorstel** verstuurd`.'),
    ex(['Wat mij betreft stellen we de lancering een kwartaal uit.', 'As far as I am concerned we postpone the launch by a quarter.'], ['Die deadline vind ik eerlijk gezegd niet haalbaar.', 'Honestly, I do not find that deadline feasible.'], ['Mag ik daar even op reageren? Over de begroting hebben we het nog niet gehad.', 'May I respond to that? We have not talked about the budget yet.'], ['Even samenvatten: Anna maakt de planning, Tom vraagt de offerte aan. Zijn we het daarover eens?', 'To summarise: Anna makes the planning, Tom requests the quotation. Are we agreed?']),
    tip('Start your turn with what the previous speaker said: `Dat punt over de planning …`, `Daarover wil ik nog iets zeggen.` It sounds connected and buys you thinking time.'),
  ], ['g3-word-order', 'g3-pronominal-adverbs'], ['agendapunt', 'notulen', 'voorzitter', 'voorstel', 'besluit', 'actiepunt', 'begroting', 'kwartaal', 'doelstelling', 'voorstellen', 'bespreken', 'samenvatten', 'afronden', 'aansluiten', 'terugkomen-op', 'ph-mag-ik-reageren', 'ph-wat-mij-betreft', 'ph-eens-daarover', 'concreet', 'haalbaar'], [
    mc('Which is correct?', ['Dat voorstel ik vind goed.', 'Dat voorstel vind ik goed.', 'Dat voorstel goed vind ik.'], 1, 'Fronted object, verb second, then subject.'),
    mc('Natural order:', ['We bespreken dat in de vergadering morgen uitgebreid.', 'We bespreken dat morgen uitgebreid in de vergadering.', 'We bespreken uitgebreid morgen dat in de vergadering.'], 1, 'Time, manner, place.'),
    mc('Which is correct?', ['Ik heb gisteren de notulen verstuurd.', 'Ik heb de notulen gisteren verstuurd.', 'Both are fine, the second is more neutral.'], 2, 'Definite objects usually come before time; after is possible for emphasis.'),
    mc('"I will come back to that":', ['Daar kom ik op terug.', 'Dat kom ik terug op.', 'Ik kom terug op het.'], 0, 'daar … op terug.'),
    fill('Wat ___ betreft beginnen we maandag.', ['mij'], 'As far as I am concerned we start on Monday.', 'wat mij betreft.'),
    fill('Ik stel ___ dat we dit volgende week bespreken. (voorstellen)', ['voor'], 'I propose that we discuss this next week.', 'stel … voor.'),
    fill('Is die deadline ___? (feasible)', ['haalbaar'], 'Is that deadline feasible?', 'halen + baar.'),
    fill('Zal ik het even ___? (summarise)', ['samenvatten'], 'Shall I summarise it?', 'samenvatten.'),
    build('That deadline I do not find feasible.', 'Die deadline vind ik niet haalbaar.', ['ik vind', 'dat'], 'Fronted object + vind ik.'),
    build('May I respond to that?', 'Mag ik daar even op reageren?', ['over', 'dat'], 'daar … op reageren.'),
    build('We have to take a decision today.', 'We moeten vandaag een besluit nemen.', ['maken', 'nemen een besluit'], 'een besluit nemen.'),
    build('Tom will join later.', 'Tom sluit later aan.', ['aansluit', 'komt'], 'sluit … aan.'),
    tr('en-nl', 'Let us wrap up. Who does what?', ['Laten we afronden. Wie doet wat?'], 'afronden.'),
    tr('nl-en', 'Over de begroting hebben we het nog niet gehad.', ['We have not talked about the budget yet.', 'We have not discussed the budget yet.'], 'het hebben over = to talk about.'),
    fix('Volgend kwartaal wij starten het project.', ['Volgend kwartaal starten we het project.', 'Volgend kwartaal starten wij het project.'], 'Inversion after a fronted time.'),
    fix('Ik stuur morgen het je.', ['Ik stuur het je morgen.'], 'Pronouns before time.'),
    dict('Wat mij betreft stellen we de lancering een kwartaal uit.', 'As far as I am concerned we postpone the launch by a quarter.', 'wat mij betreft + inversion; stellen … uit.'),
    listen('Even samenvatten: Anna maakt de planning en Tom koppelt vrijdag terug.', ['To summarise: Anna makes the planning and Tom reports back on Friday.', 'Anna reports back and Tom makes the planning.', 'The planning is postponed until Friday.'], 0, 'samenvatten; koppelt terug.'),
    speak('Mag ik daar even op reageren? Die deadline vind ik eerlijk gezegd niet haalbaar.', 'May I respond to that? Honestly, I do not find that deadline feasible.'),
    free('You are in a meeting about moving the office. Make a proposal, give one reason, and ask whether everyone agrees.', 'Ik stel voor dat we in het derde kwartaal verhuizen. Dit kwartaal is dat niet haalbaar, want de begroting is te krap. Zijn we het daarover eens?', 'I propose that we move in the third quarter. This quarter that is not feasible, because the budget is too tight. Are we agreed on that?', { hints: ['Ik stel voor dat …', '… is (niet) haalbaar, want …', 'Zijn we het daarover eens?'] }),
    auto(3, ['tr-nl-en', 'article']),
  ], [
    mc('Which is correct?', ['Morgen ik bel je.', 'Morgen bel ik je.'], 1, 'Inversion.'),
    fill('Daar kom ik zo ___ terug.', ['op'], 'I will come back to that in a moment.', 'terugkomen op.'),
    fill('We moeten een besluit ___.', ['nemen'], 'We have to take a decision.', 'een besluit nemen.'),
    build('That we will discuss next week.', 'Dat bespreken we volgende week.', ['we bespreken', 'over'], 'Fronted dat + inversion.'),
    tr('en-nl', 'Can you be more specific?', ['Kun je concreter zijn?', 'Kun je dat concreter maken?', 'Kunt u concreter zijn?'], 'concreter.'),
    speak('Wat mij betreft ronden we nu af en bespreken we de begroting volgende week.', 'As far as I am concerned we wrap up now and discuss the budget next week.'),
  ]));

  u7.push(lesson('s3u7l2', 'Professional email: formal requests, apologies and follow-ups', 'You can write a professional Dutch email to a client or organisation: refer, request with zou, apologise, attach, set a deadline and close.', [
    h('Building blocks'),
    table(['function', 'Dutch'], [['refer', '*Naar aanleiding van ons gesprek van dinsdag …'], ['purpose', '*Hierbij stuur ik u … / Ik schrijf u in verband met …'], ['polite request', '*Zou u mij de offerte kunnen toesturen? / Graag ontvang ik …'], ['apologise', '*Mijn excuses voor de late reactie. / Excuses voor het ongemak.'], ['attach', '*De factuur is bijgesloten. / In de bijlage vindt u …'], ['deadline', '*Graag uiterlijk vrijdag. / zo spoedig mogelijk'], ['offer', '*Ik licht het graag telefonisch toe. / Zal ik een afspraak inplannen?'], ['close', '*Mocht u vragen hebben, dan hoor ik het graag. / Ik zie uw reactie graag tegemoet. / Bij voorbaat dank.']]),
    p('`Graag` at the start is a compact polite imperative: `Graag uw reactie voor vrijdag.` (= Please respond before Friday.) `Mocht u …` is the formal "should you …": `Mocht u vragen hebben, dan …`'),
    h('Register ladder'),
    p('Colleague: `Hoi Tom, kun je …? Groet, Sam`. Known client: `Beste mevrouw Jansen, zou u … kunnen …? Met vriendelijke groet,`. Unknown organisation: `Geachte heer, mevrouw, … Hoogachtend,` or `Met vriendelijke groet,`.'),
    ex(['Naar aanleiding van ons telefoongesprek stuur ik u hierbij de offerte.', 'Further to our phone call I am hereby sending you the quotation.'], ['Mijn excuses voor de late reactie; ik was vorige week afwezig.', 'My apologies for the late response; I was away last week.'], ['Zou u de factuur uiterlijk vrijdag kunnen voldoen?', 'Could you settle the invoice by Friday at the latest?'], ['Mocht u nog vragen hebben, dan licht ik het graag telefonisch toe.', 'Should you have any further questions, I would be happy to explain by phone.']),
    tip('One email, one request. Put the request in its own short paragraph and the deadline in the same sentence.'),
  ], ['g3-register', 'g3-conditional'], ['offerte', 'factuur', 'opdracht', 'reactie', 'excuses', 'ongemak', 'bijsluiten', 'toelichten', 'inplannen', 'terugkoppelen', 'ph-naar-aanleiding-van', 'ph-reactie-tegemoet', 'ph-mocht-u', 'ph-bij-voorbaat-dank', 'uiterlijk', 'graag', 'zo-spoedig-mogelijk'], [
    mc('Most polite request to a client:', ['Stuur de offerte.', 'Kun je de offerte sturen?', 'Zou u mij de offerte kunnen toesturen?'], 2, 'zou u … kunnen.'),
    mc('"Mocht u vragen hebben" means', ['you may have questions', 'should you have questions', 'you must have questions'], 1, 'Formal conditional.'),
    mc('"Graag uiterlijk vrijdag" means', ['gladly after Friday', 'by Friday at the latest, please', 'on Friday evening'], 1, 'graag + uiterlijk.'),
    mc('Opening for an unknown organisation:', ['Hoi,', 'Geachte heer, mevrouw,', 'Beste allemaal,'], 1, 'Geachte heer, mevrouw,'),
    fill('Naar ___ van ons gesprek stuur ik u de offerte.', ['aanleiding'], 'Further to our conversation I am sending you the quotation.', 'naar aanleiding van.'),
    fill('Mijn ___ voor de late reactie.', ['excuses'], 'My apologies for the late response.', 'excuses.'),
    fill('De factuur is ___. (bijsluiten, participle)', ['bijgesloten'], 'The invoice is enclosed.', 'bij + gesloten.'),
    fill('Ik zie uw reactie graag ___.', ['tegemoet'], 'I look forward to your response.', 'tegemoet zien.'),
    build('Could you send me the quotation by Friday at the latest?', 'Zou u mij de offerte uiterlijk vrijdag kunnen sturen?', ['Kan', 'stuurt'], 'zou u … kunnen sturen.'),
    build('Should you have questions, please let me know.', 'Mocht u vragen hebben, dan hoor ik het graag.', ['ik hoor', 'Als'], 'mocht u … hebben, dan hoor ik.'),
    build('I will report back tomorrow.', 'Ik koppel het morgen terug.', ['terugkoppel', 'morgen het'], 'koppel … terug; pronoun before time.'),
    build('We will contact you as soon as possible.', 'Wij nemen zo spoedig mogelijk contact met u op.', ['opnemen', 'jou'], 'nemen … contact met u op.'),
    tr('en-nl', 'Apologies for the inconvenience.', ['Excuses voor het ongemak.', 'Mijn excuses voor het ongemak.'], 'ongemak.'),
    tr('nl-en', 'Ik licht het voorstel graag telefonisch toe.', ['I would be happy to explain the proposal by phone.', 'I will gladly clarify the proposal by phone.'], 'toelichten.'),
    fix('Geachte mevrouw Jansen, kun je de factuur betalen? Groetjes, Sam', ['Geachte mevrouw Jansen, zou u de factuur kunnen voldoen? Met vriendelijke groet, Sam', 'Beste mevrouw Jansen, zou u de factuur kunnen betalen? Met vriendelijke groet, Sam'], 'Formal opening needs u, zou and a formal closing.'),
    dict('Mocht u nog vragen hebben, dan hoor ik het graag.', 'Should you have any further questions, please let me know.', 'mocht u … hebben, dan.'),
    listen('Naar aanleiding van uw mail van gisteren stuur ik u hierbij de aangepaste offerte.', ['Further to your email of yesterday I am hereby sending you the revised quotation.', 'I did not receive your email of yesterday.', 'The quotation will follow tomorrow.'], 0, 'naar aanleiding van; aangepaste offerte.'),
    speak('Mijn excuses voor de late reactie. Zou u mij de factuur opnieuw kunnen toesturen?', 'My apologies for the late response. Could you send me the invoice again?'),
    read('Beste heer De Boer, Naar aanleiding van ons gesprek van dinsdag stuur ik u hierbij de offerte voor de verbouwing van uw kantoor. De werkzaamheden kunnen in week 38 starten en duren ongeveer drie weken. De prijs is inclusief materiaal, maar exclusief btw. Zou u mij uiterlijk 1 september kunnen laten weten of u akkoord gaat? Dan plannen wij de werkzaamheden in. Mocht u vragen hebben, dan licht ik de offerte graag telefonisch toe. Met vriendelijke groet, Anna Visser', [
      { q: 'When can the work start?', options: ['on 1 September', 'in week 38', 'in three weeks'], answer: 1, explain: '"in week 38 starten".' },
      { q: 'What is not included in the price?', options: ['materials', 'VAT', 'labour'], answer: 1, explain: '"exclusief btw".' },
      { q: 'What does Anna ask Mr De Boer to do?', options: ['call her', 'say by 1 September whether he agrees', 'pay in advance'], answer: 1, explain: '"uiterlijk 1 september … of u akkoord gaat".' },
    ], { en: 'Dear Mr De Boer, Further to our conversation on Tuesday I am hereby sending you the quotation for the renovation of your office. The work can start in week 38 and takes about three weeks. The price includes materials, but excludes VAT. Could you let me know by 1 September at the latest whether you agree? Then we will schedule the work. Should you have questions, I would be happy to explain the quotation by phone. Kind regards, Anna Visser' }),
    write('Write a professional email (6 to 8 sentences) to a company: refer to earlier contact, apologise for a delay, make one request with zou, give a deadline and close formally.', ['Correct opening for the relationship', 'Naar aanleiding van …', 'Excuses for something', 'One request with Zou u … kunnen …?', 'Deadline with uiterlijk or zo spoedig mogelijk', 'Mocht u vragen hebben … + Met vriendelijke groet,'], 'Beste mevrouw Jansen, Naar aanleiding van uw mail van maandag stuur ik u hierbij de gevraagde gegevens. Mijn excuses voor de late reactie; ik was vorige week afwezig. In de bijlage vindt u de getekende opdracht. Zou u mij uiterlijk vrijdag een bevestiging kunnen sturen? Dan plan ik de eerste afspraak in. Mocht u vragen hebben, dan hoor ik het graag. Met vriendelijke groet, Sam Taylor'),
  ], [
    mc('"Bij voorbaat dank" means', ['thanks afterwards', 'thank you in advance'], 1, 'bij voorbaat.'),
    fill('___ u vragen hebben, dan hoor ik het graag.', ['Mocht'], 'Should you have questions, please let me know.', 'mocht u.'),
    fill('Zou u mij de offerte ___ sturen? (can)', ['kunnen'], 'Could you send me the quotation?', 'zou … kunnen.'),
    build('The invoice has not been paid yet.', 'De factuur is nog niet betaald.', ['heeft', 'niet nog'], 'is nog niet betaald.'),
    tr('en-nl', 'I look forward to your response.', ['Ik zie uw reactie graag tegemoet.', 'Ik kijk uit naar uw reactie.'], 'tegemoet zien.'),
    speak('Naar aanleiding van ons gesprek stuur ik u hierbij de offerte. Ik zie uw reactie graag tegemoet.', 'Further to our conversation I am hereby sending you the quotation. I look forward to your response.'),
  ]));

